68	        boolean duplicate = clinicService.findAllOwners().stream()
69	            .filter(o -> !Boolean.TRUE.equals(o.getDeleted()))
70	            .map(o -> OwnerIdentityKey.telephone(o.getTelephone()) + '|' + OwnerIdentityKey.email(o.getEmail()))
