29	/**
30	 * Assigns a customerCode '<REGION>-<HASH8>' to each newly-created owner just before it is saved:
31	 * REGION is the region code derived from the postcode (its 4-digit range, else "UNKNOWN") and HASH8
32	 * is the first 8 upper-case hex characters of SHA-256 over (normalizedTelephone + lastName). Kept as
33	 * its own small aspect so this rule stays a self-contained unit rather than growing the controller
34	 * or service.
35	 */
36	@Aspect
37	@Component
38	public class OwnerCustomerCodeAdvice {
39	
40	    /** Postcode band (4-digit / 100) -> region code. */
41	    private static final Map<Integer, String> REGION = Map.of(20, "NSW", 30, "VIC", 40, "QLD");
42	
43	    private final OwnerCustomerCodeDeduplicator deduplicator;
44	
45	    public OwnerCustomerCodeAdvice(OwnerCustomerCodeDeduplicator deduplicator) {
46	        this.deduplicator = deduplicator;
47	    }
48	
49	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
50	    public void assignCustomerCode(Owner owner) {
51	        if (owner.isNew() && owner.getCustomerCode() == null) {
52	            String pc = owner.getPostcode();
53	            int band = pc != null && pc.matches("[0-9]{4}") ? Integer.parseInt(pc) / 100 : -1;
54	            try {
55	                byte[] d = MessageDigest.getInstance("SHA-256")
56	                    .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
57	                String hash8 = String.format("%02X%02X%02X%02X", d[0], d[1], d[2], d[3]);
58	                owner.setCustomerCode(deduplicator.unique(REGION.getOrDefault(band, "UNKNOWN") + "-" + hash8));
59	            }
60	            catch (NoSuchAlgorithmException e) {
61	                throw new IllegalStateException(e);
62	            }
63	        }
64	    }
65	}
