28	/**
29	 * Records whether a returned owner is a suspected duplicate. Now that the household is keyed on
30	 * (lastName, postcode), a second owner in an existing household is either rejected with 409 or,
31	 * with {@code sharesHousehold}, created as a declared member — and a declared member is not a
32	 * suspected duplicate. No other owner can share a household, so no created owner is ever flagged.
33	 * Kept as its own small advice so this rule stays a self-contained unit.
34	 */
35	@ControllerAdvice
36	public class OwnerPossibleDuplicateAdvice implements ResponseBodyAdvice<Object> {
37	
38	    @Override
39	    public boolean supports(MethodParameter returnType,
40	                            Class<? extends HttpMessageConverter<?>> converterType) {
41	        return true;
42	    }
43	
44	    @Override
45	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
46	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
47	                                  ServerHttpRequest request, ServerHttpResponse response) {
48	        if (body instanceof OwnerDto owner) {
49	            owner.setPossibleDuplicate(false);
50	            owner.setPossibleDuplicateOf(null);
51	        }
52	        return body;
53	    }
54	}
