32	/**
33	 * Flags every returned owner with whether more than 80 owners have already been created for
34	 * today's business day. Kept as its own small advice so this rule stays a self-contained unit
35	 * rather than growing the controller, the mapper or another handler.
36	 */
37	@ControllerAdvice
38	public class OwnerBulkSignupWarningAdvice implements ResponseBodyAdvice<Object> {
39	
40	    private static final int BULK_THRESHOLD = 80;
41	
42	    private final ClinicService clinicService;
43	
44	    public OwnerBulkSignupWarningAdvice(ClinicService clinicService) {
45	        this.clinicService = clinicService;
46	    }
47	
48	    @Override
49	    public boolean supports(MethodParameter returnType,
50	                            Class<? extends HttpMessageConverter<?>> converterType) {
51	        return true;
52	    }
53	
54	    @Override
55	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
56	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
57	                                  ServerHttpRequest request, ServerHttpResponse response) {
58	        if (body instanceof OwnerDto owner) {
59	            LocalDate today = RegistrationBusinessDay.effective(null);
60	            long count = clinicService.findAllOwners().stream()
61	                .map(Owner::getRegistrationDate)
62	                .filter(today::equals)
63	                .count();
64	            owner.setBulkSignupWarning(count > BULK_THRESHOLD);
65	        }
66	        return body;
67	    }
68	}
